function reverseStr(s, k) {
  const chars = s.split('');

  for (let start = 0; start < chars.length; start += 2 * k) {
    let left = start;
    let right = Math.min(start + k, chars.length) - 1;

    while (left < right) {
      const temp = chars[left];
      chars[left] = chars[right];
      chars[right] = temp;
      left++;
      right--;
    }
  }

  return chars.join('');
}

