function reverseStr(s, k) {
  let out = '';
  let i = 0;
  let flip = true;
  while (i < s.length) {
    const piece = s.slice(i, i + k);
    out += flip ? [...piece].reverse().join('') : piece;
    flip = !flip;
    i += k;
  }
  return out;
}

