function generate(rand, size) {
  if (size === 'large') {
    const n = 8000 + Math.floor(rand() * 2001);
    const pick = rand();
    const k = pick < 0.4 ? 1 + Math.floor(rand() * 50) : pick < 0.8 ? 1 + Math.floor(rand() * 3000) : 1 + Math.floor(rand() * 10000);
    let s = '';
    for (let i = 0; i < n; i++) s += String.fromCharCode(97 + Math.floor(rand() * 26));
    return [s, k];
  }
  const n = 1 + Math.floor(rand() * 12);
  const alphabet = rand() < 0.3 ? 2 : 26;
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + Math.floor(rand() * alphabet));
  const k = 1 + Math.floor(rand() * (n + 3));
  return [s, k];
}
